CREATE TABLE IF NOT EXISTS artifact_storage (team_id VARCHAR(36) PRIMARY KEY, endpoint VARCHAR(512) NOT NULL, region VARCHAR(64) NOT NULL, bucket VARCHAR(63) NOT NULL, prefix VARCHAR(200) NOT NULL, path_style BOOLEAN NOT NULL, access_key_id VARCHAR(256) NOT NULL, secret_envelope text NOT NULL, server_side_encryption VARCHAR(16) NOT NULL, verified_at BIGINT NULL, version INT NOT NULL, updated_at BIGINT NOT NULL);
